modules[S(580)] = function()
local VirtualInputManager = game:GetService(S(58))
local GuiService = game:GetService(S(616))
local click = {}
function click.Signal(button)
    return pcall(function()
        firesignal(button.Activated)
    end)
end
function click.Key(keyCode)
    return pcall(function()
        VirtualInputManager:SendKeyEvent(true, keyCode, false, game)
        task.wait(0.05)
        VirtualInputManager:SendKeyEvent(false, keyCode, false, game)
    end)
end
function click.Real(button)
    local position = button.AbsolutePosition
    local size = button.AbsoluteSize
    if size.X <= 0 or size.Y <= 0 then
        return false, S(451)
    end
    local inset = GuiService:GetGuiInset()
    local x = position.X + size.X / 2 + inset.X
    local y = position.Y + size.Y / 2 + inset.Y
    return pcall(function()
        VirtualInputManager:SendMouseMoveEvent(x, y, game)
        task.wait(0.05)
        VirtualInputManager:SendMouseButtonEvent(x, y, 0, true, game, 1)
        task.wait(0.05)
        VirtualInputManager:SendMouseButtonEvent(x, y, 0, false, game, 1)
    end)
end
return click
end
modules[S(426)] = function()
return function(import)
local HttpService = game:GetService(S(684))
local getPlaceId = import(S(736))
local log = import(S(594))
local ROOT_FOLDER = S(69)
local placeFolder = ROOT_FOLDER .. S(71) .. tostring(getPlaceId())
local filePath = placeFolder .. S(415)
local values = {}
local loaded = false
local function ensureFolders()
    if not (isfolder and makefolder) then
        return
    end
    if not isfolder(ROOT_FOLDER) then
        makefolder(ROOT_FOLDER)
    end
    if not isfolder(placeFolder) then
        makefolder(placeFolder)
    end
end
local function load()
    if loaded then
        return
    end
    loaded = true
    local ok, err = pcall(function()
        if isfile and isfile(filePath) then
            local decoded = HttpService:JSONDecode(readfile(filePath))
            if type(decoded) == S(539) then
                values = decoded
            end
        end
    end)
    if not ok then
        log(S(555) .. filePath .. S(128) .. tostring(err))
    end
end
local function save()
    local ok, err = pcall(function()
        ensureFolders()
        writefile(filePath, HttpService:JSONEncode(values))
    end)
    if not ok then
        log(S(485) .. filePath .. S(494) .. tostring(err))
    end
    return ok
end
local config = {}
function config.Get(key, default)
    load()
    local value = values[key]
    if value == nil then
        return default
    end
    return value
end
function config.Set(key, value)
    load()
    if values[key] == value then
        return
    end
    values[key] = value
    save()
end
function config.Path()
    return filePath
end
return config
end
end
