local LOG_FILE = S(81)
local function log(message)
    local line = os.date(S(294)) .. message
    print(line)
    local ok, err = pcall(function()
        if appendfile then
            if isfile and not isfile(LOG_FILE) then
                writefile(LOG_FILE, S(595))
            end
            appendfile(LOG_FILE, line .. S(381))
        elseif writefile then
            local existing = S(229)
            if isfile and isfile(LOG_FILE) then
                existing = readfile(LOG_FILE)
            end
            writefile(LOG_FILE, existing .. line .. S(126))
        else
            error(S(150))
        end
        if not (isfile and readfile) then
            error(S(315))
        end
        if not isfile(LOG_FILE) then
            error(S(133) .. LOG_FILE .. S(214))
        end
        if not readfile(LOG_FILE):find(line, 1, true) then
            error(S(443) .. LOG_FILE)
        end
    end)
    if not ok then
        print(S(344) .. LOG_FILE .. S(324) .. tostring(err))
    end
    return ok, err
end
return log
end
