modules[S(712)] = function()
return function(import)
local Players = game:GetService(S(493))
local log = import(S(774))
local reported = {}
local function getContainer()
    local playerGui = Players.LocalPlayer:FindFirstChild(S(136))
    local mineGui = playerGui and playerGui:FindFirstChild(S(734))
    local hotbar = mineGui and mineGui:FindFirstChild(S(450))
    local content = hotbar and hotbar:FindFirstChild(S(335))
    return content and content:FindFirstChild(S(367))
end
local function readCount(slotFrame)
    for _, descendant in ipairs(slotFrame:GetDescendants()) do
        if descendant:IsA(S(101)) then
            local count = descendant.Text:match(S(759))
            if count then
                return tonumber(count)
            end
        end
    end
    return nil
end
local function readSlot(slotFrame)
    local itemFrame = slotFrame:FindFirstChild(S(835))
    if not (itemFrame and itemFrame.Visible) then
        return nil
    end
    local content = itemFrame:FindFirstChild(S(233))
    local nameLabel = content and content:FindFirstChild(S(609))
    local damageLabel = content and content:FindFirstChild(S(551))
    if not (nameLabel and damageLabel) or nameLabel.Text == S(369) then
        return nil
    end
    return {
        name = nameLabel.Text,
        power = tonumber((damageLabel.Text:gsub(S(782), S(248)))) or 0,
        count = readCount(slotFrame),
    }
end
local function getMinerSlots()
    local container = getContainer()
    if not container then
        return {}
    end
    local slots = {}
    for _, slotFrame in ipairs(container:GetChildren()) do
        local slot = tonumber(slotFrame.Name)
        if slot and slot >= 1 and slot <= 9 then
            local info = readSlot(slotFrame)
            if info and (info.count == nil or info.count > 0) then
                info.slot = slot
                local key = info.name .. S(440) .. slot
                if not reported[key] then
                    reported[key] = true
                    log(S(195) .. slot .. S(132) .. info.name
                        .. S(380) .. info.power .. S(383) .. tostring(info.count))
                end
                table.insert(slots, info)
            end
        end
    end
    table.sort(slots, function(a, b)
        return a.power > b.power
    end)
    return slots
end
return getMinerSlots
end
end
